public class Main {
    static void bump(int x) {
        x++;
    }

    static void bump(int[] xs) {
        xs[0]++;
    }

    static void replace(int[] xs) {
        xs = new int[] {100};
    }

    public static void main(String[] args) {
        int a = 1;
        bump(a);
        int[] b = {1};
        bump(b);
        replace(b);
        System.out.println(a + " " + b[0]);
    }
}

